class TreeNode {
    int val;
    TreeNode left, right;

    TreeNode(int val) {
        this.val = val;
    }
}

public class Main {
    static TreeNode insert(TreeNode root, int v) {
        if (root == null) return new TreeNode(v); //~ An empty spot: the new value lives here.
        if (v < root.val) root.left = insert(root.left, v); //~ Smaller values go left…
        else root.right = insert(root.right, v); //~ …bigger ones go right.
        return root; //~ Hand the (possibly new) subtree back to the caller.
    }

    static void inorder(TreeNode n) {
        if (n == null) return; //~ No node here (null), so there's nothing to visit. Go back up.
        inorder(n.left); //~ The left subtree first,
        System.out.print(n.val + " "); //~ then this node,
        inorder(n.right); //~ then the right subtree.
    }

    public static void main(String[] args) {
        TreeNode root = null;
        int[] values = {5, 3, 8};
        for (int v : values) root = insert(root, v); //~ Insert each value into the tree.
        inorder(root); //~ Now walk it: left, node, right.
    }
}

